import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        long[] a = new long[9];

        for (int k = 1; k <= 8; k++) {
            long l = (1L << k) - 1;
            long r = 1L << (k - 1);
            a[k] = l * r;
        }

        long n = scanner.nextLong();

        for (int k = 8; k >= 1; k--) {
            if (n >= a[k] && n % a[k] == 0) {
                System.out.println(a[k]);
                return;
            }
        }
    }
}

